/**
 * Fase 3.5 / Angular: aplica cambios a una copia local de InventoryWeb.
 * No trabaja con GitHub ni PostgreSQL. Incluye archivos nuevos y respalda los originales.
 * Ejecutar desde la raíz del proyecto Angular: node aplicar_fase35_angular_v3.mjs
 */
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const dryRun = process.argv.includes('--check');
if (!fs.existsSync(path.join(root, 'src', 'app', 'app.routes.ts')) || !fs.existsSync(path.join(root, 'package.json'))) {
  throw new Error('Abre la terminal en la raíz de InventoryWeb (donde están package.json y src/app).');
}
const updates = new Map();
const original = new Map();
const newlineStyle = new Map();
const notices = [];
function load(rel) {
  const file = path.join(root, rel);
  if (!fs.existsSync(file)) throw new Error(`No existe el archivo esperado: ${rel}`);
  const text = fs.readFileSync(file, 'utf8');
  original.set(rel, text);
  newlineStyle.set(rel, text.includes('\r\n') ? '\r\n' : '\n');
  return text.replace(/\r\n/g, '\n');
}
function patch(rel, callback) {
  const before = load(rel);
  const after = callback(before);
  if (typeof after !== 'string') throw new Error(`Reemplazo inválido en ${rel}`);
  if (after !== before) updates.set(rel, after);
  else notices.push(`Ya adaptado, sin cambios: ${rel}`);
}
function once(text, before, after, context) {
  const count = text.split(before).length - 1;
  if (text.includes(after)) return text; // La modificación ya está aplicada.
  if (count === 1) return text.replace(before, after);
  throw new Error(`${context}: se esperaba exactamente 1 coincidencia (hay ${count}). El archivo es diferente al esperado. No se modificó ningún archivo.`);
}

patch('src/app/core/services/inventories.ts', s => {
  if (!/\bisMaster\??\s*:\s*boolean/.test(s)) {
    const pattern = /(^[ \t]*isActive\??\s*:\s*boolean\s*;\n)([ \t]*companyId\s*:)/gm;
    const matches = [...s.matchAll(pattern)];
    if (matches.length !== 1) throw new Error(`inventories / tipo maestro: no encontré el lugar para declarar isMaster (coincidencias: ${matches.length}). No se modificó ningún archivo.`);
    s = s.replace(pattern, (_, active, company) => active + '  isMaster?: boolean;\n' + company);
  }
  return s;
});
