// Archivos nuevos incluidos en el propio aplicador. No necesitas 'archivos_nuevos'.
// Se comprueban antes de editar. Si ya los copiaste, no se sobrescriben.
const resources = new Map([
  ["src/app/core/services/inventory-context.ts", "import { isPlatformBrowser } from '@angular/common';\nimport { Injectable, PLATFORM_ID, inject } from '@angular/core';\nimport { BehaviorSubject } from 'rxjs';\nimport { InventorySummary } from './inventories';\n\n/** Inventario operativo elegido por el usuario; el maestro nunca es operativo. */\n@Injectable({ providedIn: 'root' })\nexport class InventoryContextService {\n  private readonly platformId = inject(PLATFORM_ID);\n  private readonly state = new BehaviorSubject<number | null>(null);\n  private available: InventorySummary[] = [];\n  readonly activeInventoryId$ = this.state.asObservable();\n\n  get activeInventoryId(): number | null { return this.state.value; }\n  get options(): InventorySummary[] { return [...this.available]; }\n\n  private get key(): string {\n    if (!isPlatformBrowser(this.platformId)) return 'inventory-active-unknown';\n    try {\n      const session = JSON.parse(localStorage.getItem('userSession') || '{}');\n      return `inventory-active-${Number(session.companyId) || 0}-${Number(session.id) || 0}`;\n    } catch { return 'inventory-active-unknown'; }\n  }\n\n  initialize(inventories: InventorySummary[], userId: number): void {\n    this.available = (inventories || []).filter(i => i.isActive && !i.isMaster);\n    const saved = isPlatformBrowser(this.platformId) ? Number(localStorage.getItem(this.key)) : 0;\n    const candidate = this.available.find(i => i.id === saved)\n      ?? this.available.find(i => i.userId === userId)\n      ?? this.available[0];\n    this.state.next(candidate?.id ?? null);\n    if (candidate && isPlatformBrowser(this.platformId)) localStorage.setItem(this.key, String(candidate.id));\n  }\n\n  select(id: number): boolean {\n    const found = this.available.some(i => i.id === id);\n    if (!found) return false;\n    this.state.next(id);\n    if (isPlatformBrowser(this.platformId)) localStorage.setItem(this.key, String(id));\n    return true;\n  }\n}\n"],
  ["src/app/features/master-catalogs/master-catalogs.html", "<section class=\"catalog-page\">\n  <header><div><h1>Catálogo general</h1><p>Todos los inventarios de la empresa utilizan estos registros. Las claves del sistema no se muestran aquí.</p></div><button type=\"button\" (click)=\"refresh()\" [disabled]=\"loading\">Actualizar</button></header>\n  <div class=\"tabs\"><button type=\"button\" [class.active]=\"tab==='suppliers'\" (click)=\"tab='suppliers'\">Proveedores</button><button type=\"button\" [class.active]=\"tab==='parameters'\" (click)=\"tab='parameters'\">Parámetros generales</button></div>\n  <p *ngIf=\"loading\" role=\"status\">Consultando catálogos...</p>\n  <div class=\"panel\" *ngIf=\"tab==='suppliers'\">\n    <form (ngSubmit)=\"saveSupplier()\">\n      <h2>{{editingSupplierId?'Editar proveedor':'Nuevo proveedor'}}</h2>\n      <div class=\"fields\"><label>RUC <input [(ngModel)]=\"supplier.ruc\" name=\"ruc\" maxlength=\"11\" inputmode=\"numeric\" required /></label><label>Razón social <input [(ngModel)]=\"supplier.businessName\" name=\"businessName\" maxlength=\"250\" required /></label><label>Contacto <input [(ngModel)]=\"supplier.contactName\" name=\"contactName\" /></label><label>Teléfono <input [(ngModel)]=\"supplier.phone\" name=\"phone\" /></label><label>Correo <input [(ngModel)]=\"supplier.email\" name=\"email\" type=\"email\" /></label><label>Dirección <input [(ngModel)]=\"supplier.address\" name=\"address\" /></label></div>\n      <div class=\"actions\"><button type=\"submit\" class=\"primary\" [disabled]=\"saving\">{{saving?'Guardando...':editingSupplierId?'Guardar cambios':'Registrar proveedor'}}</button><button *ngIf=\"editingSupplierId\" type=\"button\" (click)=\"newSupplier()\">Cancelar edición</button></div>\n    </form>\n    <div class=\"list\"><h2>Proveedores de la empresa ({{suppliers.length}})</h2><table><thead><tr><th>RUC</th><th>Razón social</th><th>Estado</th><th *ngIf=\"canManage\">Acciones</th></tr></thead><tbody><tr *ngFor=\"let item of suppliers\"><td>{{item.ruc}}</td><td>{{item.businessName}}</td><td>{{item.isActive?'Activo':'Inactivo'}}</td><td *ngIf=\"canManage\"><button type=\"button\" (click)=\"editSupplier(item)\" [disabled]=\"!item.isActive\">Editar</button><button type=\"button\" (click)=\"disableSupplier(item)\" [disabled]=\"!item.isActive\">Desactivar</button></td></tr></tbody></table><p *ngIf=\"!suppliers.length\">Sin proveedores registrados.</p></div>\n  </div>\n  <div class=\"panel\" *ngIf=\"tab==='parameters'\">\n    <form (ngSubmit)=\"saveParameter()\"><h2>{{editingParameterId?'Editar parámetro':'Nuevo parámetro general'}}</h2><div class=\"fields\"><label>Tipo <input [(ngModel)]=\"parameter.parameterType\" name=\"parameterType\" maxlength=\"100\" required placeholder=\"Ej. UnidadBase\" /></label><label>Nombre <input [(ngModel)]=\"parameter.name\" name=\"parameterName\" maxlength=\"255\" required /></label><label>Descripción / valor <textarea [(ngModel)]=\"parameter.description\" name=\"description\" rows=\"2\"></textarea></label></div><p class=\"hint\">Para parámetros comunes. Las contraseñas, tokens y claves de API tienen una gestión separada.</p><div class=\"actions\"><button type=\"submit\" class=\"primary\" [disabled]=\"saving\">{{saving?'Guardando...':editingParameterId?'Guardar cambios':'Registrar parámetro'}}</button><button *ngIf=\"editingParameterId\" type=\"button\" (click)=\"newParameter()\">Cancelar edición</button></div></form>\n    <div class=\"list\"><h2>Parámetros visibles ({{parameters.length}})</h2><table><thead><tr><th>Tipo</th><th>Nombre</th><th>Valor / descripción</th><th *ngIf=\"canManage\">Acciones</th></tr></thead><tbody><tr *ngFor=\"let item of parameters\"><td>{{item.parameterType}}</td><td>{{item.name}}</td><td>{{item.description||'—'}}</td><td *ngIf=\"canManage\"><button type=\"button\" (click)=\"editParameter(item)\">Editar</button><button type=\"button\" (click)=\"deleteParameter(item)\">Eliminar</button></td></tr></tbody></table><p *ngIf=\"!parameters.length\">Sin parámetros generales visibles.</p></div>\n  </div>\n</section>\n"],
  ["src/app/features/master-catalogs/master-catalogs.scss", ":host{display:block;color:#e8f2fb}\n.catalog-page{display:flex;flex-direction:column;gap:14px}\nheader{display:flex;align-items:center;justify-content:space-between;gap:12px}\nh1{margin:0;font-size:23px}h2{margin:0 0 12px;font-size:16px}p{margin:4px 0;color:#aebdca;font-size:12px}\n.tabs{display:flex;gap:8px;flex-wrap:wrap}\nbutton{border:1px solid #526c7c;border-radius:7px;background:#233747;color:#edf6fc;padding:8px 12px;cursor:pointer}\nbutton:disabled{opacity:.5;cursor:not-allowed}.tabs button.active,.primary{background:#93bb43;border-color:#93bb43;color:#172509;font-weight:700}\n.panel{display:grid;grid-template-columns:minmax(270px,.9fr) minmax(320px,1.6fr);gap:14px}\n.panel form,.list{background:#1a2a36;border:1px solid #3b5465;border-radius:12px;padding:16px;min-width:0}\n.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}\n.fields label{display:flex;flex-direction:column;gap:5px;font-size:12px}\n.fields input,.fields textarea{background:#111d27;border:1px solid #536b7c;color:#f3f8fb;padding:10px;border-radius:7px;font:inherit;min-width:0}\n.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}\n.list{overflow:auto}.list table{width:100%;border-collapse:collapse;font-size:12px}.list th,.list td{padding:10px;border-bottom:1px solid #364e5d;text-align:left}\n.list th{color:#c5d8e3;background:#243a48}.list td button{font-size:11px;margin:2px}\n.hint{margin-top:12px;line-height:1.5}\n@media(max-width:900px){.panel{grid-template-columns:1fr}}\n"],
  ["src/app/features/master-catalogs/master-catalogs.ts", "import { CommonModule, isPlatformBrowser } from '@angular/common';\nimport { Component, OnInit, PLATFORM_ID, inject } from '@angular/core';\nimport { FormsModule } from '@angular/forms';\nimport { HttpClient } from '@angular/common/http';\nimport type { Observable } from 'rxjs';\nimport { MatIconModule } from '@angular/material/icon';\nimport { InventoryContextService } from '../../core/services/inventory-context';\nimport { ToastService } from '../../shared/toast/toast.service';\n\ninterface SupplierRecord {\n  id: number; inventoryId: number; companyId: number; ruc: string; businessName: string;\n  contactName?: string | null; phone?: string | null; email?: string | null;\n  address?: string | null; statusId: number; isActive: boolean; reused?: boolean;\n}\ninterface ParameterRecord {\n  id: number; inventoryId: number; companyId: number; parameterType: string;\n  name: string; description?: string | null; reused?: boolean;\n}\n\n@Component({\n  selector: 'app-master-catalogs', standalone: true,\n  imports: [CommonModule, FormsModule, MatIconModule],\n  templateUrl: './master-catalogs.html', styleUrl: './master-catalogs.scss'\n})\nexport class MasterCatalogsComponent implements OnInit {\n  private readonly http = inject(HttpClient);\n  private readonly inventories = inject(InventoryContextService);\n  private readonly toast = inject(ToastService);\n  private readonly platformId = inject(PLATFORM_ID);\n  private readonly apiRoot = 'https://localhost:7295/api';\n  tab: 'suppliers' | 'parameters' = 'suppliers';\n  suppliers: SupplierRecord[] = [];\n  parameters: ParameterRecord[] = [];\n  loading = false;\n  saving = false;\n  editingSupplierId: number | null = null;\n  editingParameterId: number | null = null;\n  supplier: SupplierRecord = this.emptySupplier();\n  parameter: ParameterRecord = this.emptyParameter();\n\n  get canManage(): boolean {\n    if (!isPlatformBrowser(this.platformId)) return false;\n    try { return [1, 2].includes(Number(JSON.parse(localStorage.getItem('userSession') || '{}').roleId)); }\n    catch { return false; }\n  }\n  ngOnInit(): void { this.refresh(); }\n  private emptySupplier(): SupplierRecord {\n    return {id:0,inventoryId:0,companyId:0,ruc:'',businessName:'',contactName:'',phone:'',email:'',address:'',statusId:1,isActive:true};\n  }\n  private emptyParameter(): ParameterRecord {\n    return {id:0,inventoryId:0,companyId:0,parameterType:'',name:'',description:''};\n  }\n  refresh(): void {\n    if (this.loading) return;\n    this.loading = true;\n    this.http.get<SupplierRecord[]>(`${this.apiRoot}/Suppliers`).subscribe({\n      next: list => {this.suppliers = list || [];this.loading = false;},\n      error: () => {this.loading = false;this.toast.error('No se pudieron consultar los proveedores.');}\n    });\n    this.http.get<ParameterRecord[]>(`${this.apiRoot}/Parameters`).subscribe({\n      next: list => this.parameters = list || [],\n      error: () => this.toast.error('No se pudieron consultar los parámetros generales.')\n    });\n  }\n  newSupplier(): void {this.supplier=this.emptySupplier();this.editingSupplierId=null;}\n  editSupplier(item: SupplierRecord): void {if (!this.canManage) return;this.supplier={...item};this.editingSupplierId=item.id;this.tab='suppliers';}\n  saveSupplier(): void {\n    const ruc=String(this.supplier.ruc).trim();\n    const businessName=String(this.supplier.businessName).trim();\n    if (!/^\\d{11}$/.test(ruc) || !businessName) {this.toast.warning('Ingresa un RUC de 11 dígitos y la razón social.');return;}\n    const inventoryId=this.inventories.activeInventoryId;\n    if (!inventoryId) {this.toast.warning('Selecciona un inventario personal o compartido.');return;}\n    this.saving=true;\n    const payload={...this.supplier,ruc,businessName,inventoryId};\n    const req: Observable<SupplierRecord | void> = this.editingSupplierId\n      ? this.http.put<void>(`${this.apiRoot}/Suppliers/${this.editingSupplierId}`,payload)\n      : this.http.post<SupplierRecord>(`${this.apiRoot}/Suppliers`,payload);\n    req.subscribe({\n      next: item => {\n        this.saving=false;\n        if (item && typeof item==='object' && 'reused' in item && item.reused)\n          this.toast.info('El proveedor ya estaba registrado. Se reutilizó el mismo ID.','Proveedor existente');\n        else this.toast.success(this.editingSupplierId?'Proveedor actualizado.':'Proveedor incorporado al catálogo maestro.');\n        this.newSupplier();this.refresh();\n      },\n      error: err => {this.saving=false;this.toast.error(String(err?.error?.error||'No fue posible guardar el proveedor.'));}\n    });\n  }\n  disableSupplier(item: SupplierRecord): void {\n    if (!this.canManage || !confirm(`¿Desactivar al proveedor ${item.businessName}?`))return;\n    this.http.delete<void>(`${this.apiRoot}/Suppliers/${item.id}`).subscribe({\n      next:()=>{this.toast.success('Proveedor desactivado.');this.refresh();},\n      error:err=>this.toast.error(String(err?.error?.error||'No se pudo desactivar el proveedor.'))\n    });\n  }\n  newParameter(): void {this.parameter=this.emptyParameter();this.editingParameterId=null;}\n  editParameter(item: ParameterRecord): void {if (!this.canManage)return;this.parameter={...item};this.editingParameterId=item.id;this.tab='parameters';}\n  saveParameter(): void {\n    if (!this.parameter.parameterType.trim() || !this.parameter.name.trim()){\n      this.toast.warning('Indica el tipo y el nombre del parámetro.');return;\n    }\n    const inventoryId=this.inventories.activeInventoryId;\n    if (!inventoryId) {this.toast.warning('Selecciona un inventario de trabajo.');return;}\n    this.saving=true;\n    const payload={...this.parameter,inventoryId};\n    const req: Observable<ParameterRecord | void> = this.editingParameterId\n      ? this.http.put<void>(`${this.apiRoot}/Parameters/${this.editingParameterId}`,payload)\n      : this.http.post<ParameterRecord>(`${this.apiRoot}/Parameters`,payload);\n    req.subscribe({\n      next: item => {\n        this.saving=false;\n        if (item && typeof item==='object' && 'reused' in item && item.reused)\n          this.toast.info('Este parámetro ya existe. Se reutilizó su ID.','Parámetro existente');\n        else this.toast.success(this.editingParameterId?'Parámetro actualizado.':'Parámetro creado en el maestro.');\n        this.newParameter();this.refresh();\n      },\n      error:err=>{this.saving=false;this.toast.error(String(err?.error?.error||'No fue posible guardar el parámetro.'));}\n    });\n  }\n  deleteParameter(item: ParameterRecord): void {\n    if(!this.canManage || !confirm(`¿Eliminar el parámetro ${item.name}?`))return;\n    this.http.delete<void>(`${this.apiRoot}/Parameters/${item.id}`).subscribe({\n      next:()=>{this.toast.success('Parámetro eliminado.');this.refresh();},\n      error:err=>this.toast.error(String(err?.error?.error||'No se pudo eliminar el parámetro.'))\n    });\n  }\n}\n"],
  ["src/app/features/master-history/master-history.html", "<section class=\"master-history\">\n  <header>\n    <div><h1>Historial general</h1><p>Entradas y salidas de los inventarios personales de esta empresa.</p></div>\n    <button type=\"button\" (click)=\"load()\" [disabled]=\"loading\"><mat-icon>refresh</mat-icon> Actualizar</button>\n  </header>\n  <form class=\"filters\" (ngSubmit)=\"applyFilters()\">\n    <label>Inventario (ID)<input name=\"inventoryId\" [(ngModel)]=\"inventoryId\" type=\"number\" min=\"1\" placeholder=\"Todos\" /></label>\n    <label>Propietario (ID)<input name=\"userId\" [(ngModel)]=\"userId\" type=\"number\" min=\"1\" placeholder=\"Todos\" /></label>\n    <label>Usuario responsable (ID)<input name=\"actorUserId\" [(ngModel)]=\"actorUserId\" type=\"number\" min=\"1\" placeholder=\"Todos\" /></label>\n    <label>Movimiento<select name=\"actionId\" [(ngModel)]=\"actionId\"><option value=\"\">Todos</option><option value=\"1\">Entradas</option><option value=\"2\">Salidas</option></select></label>\n    <label>Desde<input name=\"from\" [(ngModel)]=\"from\" type=\"date\" /></label>\n    <label>Hasta<input name=\"to\" [(ngModel)]=\"to\" type=\"date\" /></label>\n    <button type=\"submit\" [disabled]=\"loading\">Filtrar</button>\n  </form>\n  <div role=\"status\" *ngIf=\"loading\" class=\"status\">Consultando movimientos...</div>\n  <div role=\"alert\" *ngIf=\"error\" class=\"error\">{{error}}</div>\n  <div class=\"table-wrapper\" *ngIf=\"!loading && !error\">\n    <table>\n      <thead><tr><th>Fecha</th><th>Tipo</th><th>Inventario</th><th>Propietario</th><th>Responsable (ID)</th><th>Artículo</th><th>Cantidad</th><th>Observación</th></tr></thead>\n      <tbody><tr *ngFor=\"let row of items\">\n        <td>{{row.movementDate | date:'dd/MM/yyyy HH:mm'}}</td>\n        <td><span class=\"type\" [class.out]=\"row.actionId===2\">{{row.actionId===1?'Entrada':'Salida'}}</span></td>\n        <td>{{row.inventoryName}} <small>#{{row.inventoryId}}</small></td>\n        <td>{{row.username}}</td>\n        <td>{{row.actorUserId ?? '—'}}</td>\n        <td>{{row.articleName}} <small>{{row.articleCode}}</small></td>\n        <td>{{row.amount ?? '—'}}</td>\n        <td>{{row.observation || '—'}}</td>\n      </tr></tbody>\n    </table>\n    <p *ngIf=\"!items.length\" class=\"status\">No existen movimientos para estos filtros.</p>\n  </div>\n  <footer><span>{{total}} movimientos encontrados</span><div><button type=\"button\" (click)=\"previous()\" [disabled]=\"page<=1||loading\">Anterior</button><strong>Página {{page}}</strong><button type=\"button\" (click)=\"next()\" [disabled]=\"page*pageSize>=total||loading\">Siguiente</button></div></footer>\n</section>\n"],
  ["src/app/features/master-history/master-history.scss", ":host {display:block;color:#e9f1f8}\n.master-history {display:flex;flex-direction:column;gap:14px;min-width:0}\nheader,footer {display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}\nh1 {margin:0 0 3px;font-size:23px}\np {margin:0;color:#b2c2d1;font-size:12px}\nbutton {display:inline-flex;align-items:center;justify-content:center;gap:5px;padding:9px 13px;background:#2c4050;color:#f4f8fa;border:1px solid #597080;border-radius:8px;cursor:pointer}\nbutton:disabled {opacity:.5;cursor:not-allowed}\nbutton[type=submit]{background:#94bb44;border-color:#94bb44;color:#14230c;font-weight:700}\n.filters {display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:12px;padding:14px;background:#192936;border:1px solid #384d5c;border-radius:12px;align-items:end}\n.filters label{display:flex;flex-direction:column;gap:5px;font-size:12px;color:#d2dfe9}\n.filters input,.filters select{background:#111c26;border:1px solid #586e80;border-radius:7px;color:#f4f8fa;padding:9px;min-width:0}\n.table-wrapper{border:1px solid #384d5c;border-radius:12px;overflow:auto;background:#182733}\ntable{width:100%;min-width:980px;border-collapse:collapse;text-align:left;font-size:12px}\nth,td{padding:12px 9px;border-bottom:1px solid #344657;vertical-align:middle}\nth{position:sticky;top:0;background:#243747;color:#dfeaf5}\ntd small{display:block;color:#a9bbc9;margin-top:3px}\n.type{display:inline-flex;background:#33472d;color:#cceb99;border-radius:14px;padding:4px 7px}\n.type.out{background:#51372d;color:#ffc3a4}\n.status{padding:20px;text-align:center;color:#c8d4df}\n.error{padding:12px;color:#ffb6b6}\nfooter{font-size:12px;color:#b7c8d6}footer div{display:flex;align-items:center;gap:10px}\n"],
  ["src/app/features/master-history/master-history.ts", "import { CommonModule } from '@angular/common';\nimport { Component, OnInit, inject } from '@angular/core';\nimport { FormsModule } from '@angular/forms';\nimport { HttpClient, HttpParams } from '@angular/common/http';\nimport { MatIconModule } from '@angular/material/icon';\nimport { ToastService } from '../../shared/toast/toast.service';\n\ninterface MasterMovementRow {\n  id: number;\n  movementDate: string;\n  actionId: number;\n  amount: number | null;\n  employeeId: number | null;\n  observation: string | null;\n  inventoryId: number;\n  inventoryName: string;\n  userId: number;\n  username: string;\n  actorUserId?: number | null;\n  articleId: number;\n  articleName: string;\n  articleCode: string;\n}\ninterface MasterHistoryResponse { items: MasterMovementRow[]; total: number; page: number; pageSize: number; }\n\n@Component({\n  selector: 'app-master-history', standalone: true,\n  imports: [CommonModule, FormsModule, MatIconModule],\n  templateUrl: './master-history.html', styleUrl: './master-history.scss'\n})\nexport class MasterHistoryComponent implements OnInit {\n  private readonly http = inject(HttpClient);\n  private readonly toast = inject(ToastService);\n  readonly api = 'https://localhost:7295/api/Movements/master/history';\n  items: MasterMovementRow[] = [];\n  total = 0;\n  loading = false;\n  page = 1;\n  pageSize = 30;\n  inventoryId = '';\n  userId = '';\n  actorUserId = '';\n  actionId = '';\n  from = '';\n  to = '';\n  error = '';\n\n  ngOnInit(): void { this.load(); }\n  applyFilters(): void { this.page = 1; this.load(); }\n  next(): void { if (this.page * this.pageSize < this.total) { this.page++; this.load(); } }\n  previous(): void { if (this.page > 1) { this.page--; this.load(); } }\n\n  load(): void {\n    if (this.loading) return;\n    let params = new HttpParams().set('page', this.page).set('pageSize', this.pageSize);\n    for (const [key, value] of [\n      ['inventoryId', this.inventoryId], ['userId', this.userId],\n      ['actorUserId', this.actorUserId], ['actionId', this.actionId]\n    ] as const) {\n      if (value.trim() !== '') params = params.set(key, value.trim());\n    }\n    if (this.from) params = params.set('from', new Date(`${this.from}T00:00:00`).toISOString());\n    if (this.to) params = params.set('to', new Date(`${this.to}T23:59:59`).toISOString());\n    this.loading = true;\n    this.error = '';\n    this.http.get<MasterHistoryResponse>(this.api, { params }).subscribe({\n      next: result => { this.items = result.items ?? []; this.total = result.total ?? 0; this.loading = false; },\n      error: err => {\n        this.loading = false;\n        this.error = String(err?.error?.error || 'No se pudo consultar el historial de la empresa.');\n        this.toast.error(this.error, 'Historial administrativo');\n      }\n    });\n  }\n}\n"],
  ["src/app/shared/catalog-similar-dialog/catalog-similar-dialog.ts", "import { CommonModule } from '@angular/common';\nimport { Component, inject } from '@angular/core';\nimport { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';\nimport { MatIconModule } from '@angular/material/icon';\n\nexport interface CatalogSimilarMatch { id: number; name: string; }\nexport interface CatalogSimilarData {\n  type: string;\n  enteredName: string;\n  matches: CatalogSimilarMatch[];\n}\nexport type CatalogSimilarChoice = { action: 'reuse'; id: number } | { action: 'create' } | null;\n\n/** Confirmación explícita: el nombre parecido no se fusiona automáticamente. */\n@Component({\n  selector: 'app-catalog-similar-dialog',\n  standalone: true,\n  imports: [CommonModule, MatDialogModule, MatIconModule],\n  template: `\n    <div class=\"catalog-similar-dialog\">\n      <h2 mat-dialog-title><mat-icon>warning_amber</mat-icon> Posible duplicado</h2>\n      <mat-dialog-content>\n        <p>Quieres registrar <strong>{{data.enteredName}}</strong>, pero encontramos {{data.type}} similares.</p>\n        <p>Selecciona un registro existente o confirma que deseas crear uno nuevo.</p>\n        <div class=\"match\" *ngFor=\"let item of data.matches\">\n          <span><strong>{{item.name}}</strong> <small>ID {{item.id}}</small></span>\n          <button type=\"button\" (click)=\"reuse(item.id)\">Utilizar</button>\n        </div>\n      </mat-dialog-content>\n      <mat-dialog-actions align=\"end\">\n        <button type=\"button\" (click)=\"cancel()\">Cancelar</button>\n        <button type=\"button\" class=\"new\" (click)=\"create()\">Crear de todos modos</button>\n      </mat-dialog-actions>\n    </div>\n  `,\n  styles: [`\n    .catalog-similar-dialog { background:#17232f; color:#eef5fa; padding:6px; min-width:min(340px,85vw); }\n    h2 {display:flex;align-items:center;gap:8px;color:#f4f7fc;font-size:19px}\n    h2 mat-icon {color:#e9b763} p {font-size:13px;line-height:1.6}\n    .match {display:flex;align-items:center;justify-content:space-between;gap:16px;padding:9px 0;border-bottom:1px solid #425464}\n    small {color:#b6c6d4;margin-left:6px}\n    button {background:#273b4b;color:#ecf5fd;border:1px solid #657b8d;border-radius:7px;padding:8px 12px;cursor:pointer}\n    button.new {background:#99bf4a;color:#17240d;font-weight:700}\n    mat-dialog-actions {gap:8px;padding-top:14px}\n  `]\n})\nexport class CatalogSimilarDialogComponent {\n  readonly data: CatalogSimilarData = inject(MAT_DIALOG_DATA);\n  private readonly ref = inject(MatDialogRef<CatalogSimilarDialogComponent, CatalogSimilarChoice>);\n  reuse(id: number): void { this.ref.close({ action: 'reuse', id }); }\n  create(): void { this.ref.close({ action: 'create' }); }\n  cancel(): void { this.ref.close(null); }\n}\n"],
]);
const pendingNewFiles = [];
for (const [rel, content] of resources) {
  const target = path.join(root, rel);
  if (fs.existsSync(target)) {
    const existing = fs.readFileSync(target, 'utf8');
    if (existing.replace(/\r\n/g, '\n') !== content.replace(/\r\n/g, '\n')) {
      throw new Error(`El archivo \"${rel}\" ya existe con cambios distintos. No lo sobrescribiremos. No se ha modificado ningún archivo.`);
    }
    notices.push(`Archivo nuevo ya instalado; se conserva: ${rel}`);
  } else {
    pendingNewFiles.push({rel, content});
  }
}
console.log(`Verificados ${updates.size} reemplazos pendientes y ${pendingNewFiles.length} archivos nuevos pendientes.`);
for (const notice of notices) console.log('  • ' + notice);
if(dryRun){console.log('Verificación correcta: no se ha modificado ningún archivo.');process.exit(0);}
const backup=path.join(root, '_respaldo_previo_fase35_angular');
if(fs.existsSync(backup) && (updates.size || pendingNewFiles.length)) throw new Error('Ya existe _respaldo_previo_fase35_angular. Conserva ese respaldo y no apliques parches dos veces sin revisar.');
for(const [rel,source] of original){const dest=path.join(backup,rel);fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,source,'utf8');}
for(const [rel,text] of updates){const dest=path.join(root,rel);fs.writeFileSync(dest, newlineStyle.get(rel)==='\r\n' ? text.replace(/\n/g,'\r\n') : text,'utf8');}
for(const file of pendingNewFiles){const dest=path.join(root,file.rel);fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,file.content,'utf8');}
console.log(updates.size || pendingNewFiles.length ? 'Cambios aplicados en la copia local. Respaldo:' : 'Ya estaba todo aplicado, no se modificó nada.', updates.size || pendingNewFiles.length ? backup : '');
console.log('Siguiente paso: npm install && npm run build');
